#!/usr/bin/env python3
import struct
import sys
import binascii
import os

def try_parse_as_floats(filename):
    with open(filename, 'rb') as f:
        data = f.read()

    print(f"File size: {len(data)} bytes")

    # Try to interpret as 32-bit floats
    if len(data) % 4 == 0:
        print(f"File can be interpreted as {len(data)//4} 32-bit floats")
        for i in range(0, min(40, len(data)), 4):
            try:
                float_val = struct.unpack('f', data[i:i+4])[0]
                print(f"Bytes {i}-{i+3}: {float_val}")
            except:
                print(f"Bytes {i}-{i+3}: [Error parsing]")

    # Try to interpret as 64-bit floats (double)
    if len(data) % 8 == 0:
        print(f"\nFile can be interpreted as {len(data)//8} 64-bit floats")
        for i in range(0, min(80, len(data)), 8):
            try:
                double_val = struct.unpack('d', data[i:i+8])[0]
                print(f"Bytes {i}-{i+7}: {double_val}")
            except:
                print(f"Bytes {i}-{i+7}: [Error parsing]")

    # Check if this might be a PGM file (image format)
    try:
        with open(filename, 'r') as f:
            content = f.read(100)  # Read just the beginning
            if content.startswith('P2') or content.startswith('P5'):
                print("\nFile might be a PGM image!")
    except:
        pass

    # Check for common file signatures
    signatures = {
        b'\x89PNG': 'PNG image',
        b'BM': 'BMP image',
        b'\xff\xd8\xff': 'JPEG image',
        b'GIF8': 'GIF image',
        b'PK\x03\x04': 'ZIP archive',
        b'7z\xbc\xaf\x27\x1c': '7-Zip archive',
        b'\x25\x50\x44\x46': 'PDF document',
    }

    for sig, file_type in signatures.items():
        if data.startswith(sig):
            print(f"\nDetected file signature: {file_type}")

    # Write data to a file with .bin extension for further analysis
    output_bin = os.path.splitext(filename)[0] + ".bin"
    with open(output_bin, 'wb') as f:
        f.write(data)
    print(f"\nData written to {output_bin} for binary analysis")

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <filename>")
        sys.exit(1)

    try_parse_as_floats(sys.argv[1])

#!/usr/bin/env python3
import sys
import struct
import numpy as np
from PIL import Image
import binascii

def extract_float_values(filename):
    with open(filename, 'rb') as f:
        data = f.read()

    print(f"File size: {len(data)} bytes")

    # Check if this is a text file that might contain encoded floats
    if all(32 <= b <= 126 or b in (9, 10, 13) for b in data):
        print("File appears to be text, attempting to interpret as encoded floats")

        # Try different width values to find a pattern
        floats = []

        try:
            # Strip any whitespace
            data_str = data.decode('ascii').strip()

            # Approach 1: Try converting from hexadecimal
            if all(c in "0123456789ABCDEFabcdef \t\r\n" for c in data_str):
                hex_values = data_str.split()
                for hex_val in hex_values:
                    try:
                        if len(hex_val) == 8:  # 32-bit float
                            val = struct.unpack('!f', binascii.unhexlify(hex_val))[0]
                            floats.append(val)
                    except:
                        pass

            # Approach 2: Try base64 or similar encoding
            if not floats:
                try:
                    decoded = binascii.a2b_base64(data)
                    if len(decoded) % 4 == 0:
                        floats = list(struct.unpack('<' + 'f' * (len(decoded) // 4), decoded))
                except:
                    pass

            # Approach 3: Try direct parsing of float literals
            if not floats:
                try:
                    floats = [float(x) for x in data_str.split()]
                except:
                    pass

            # Approach 4: If we still have no floats, this might be an esoteric encoding
            # Try converting ASCII values to bytes based on common patterns
            if not floats:
                # This might be a custom encoding like using ASCII characters as bytes
                # Let's try to extract values by reading every 4 ASCII chars as a 32-bit value
                if len(data) % 4 == 0:
                    num_values = len(data) // 4
                    try:
                        floats = list(struct.unpack('<' + 'f' * num_values, data))
                    except:
                        pass

                if not floats:
                    # Try every 4 ASCII chars as bytes in various orders
                    try:
                        # Try as big-endian
                        floats = list(struct.unpack('>' + 'f' * num_values, data))
                    except:
                        pass

            # Approach 5: Try BF encoding approach (likely not useful for this challenge)
            # I'm including it just in case it's a weird encoding
            if not floats and all(c in '><+-.,[]' for c in data_str):
                print("This appears to be Brainfuck code, trying to interpret...")
                # Implementation would go here

        except Exception as e:
            print(f"Error processing text: {e}")

    if not floats:
        print("Could not extract float values. Let's try IEEE 754 conversion directly...")

        # Try direct binary interpretation
        if len(data) % 4 == 0:
            num_floats = len(data) // 4
            try:
                # Little-endian floats
                floats = list(struct.unpack('<' + 'f' * num_floats, data))
            except:
                try:
                    # Big-endian floats
                    floats = list(struct.unpack('>' + 'f' * num_floats, data))
                except:
                    print("Could not interpret as IEEE 754 floats")
                    return None

    if floats:
        print(f"Extracted {len(floats)} float values")
        print(f"Sample: {floats[:10]}")
        return floats
    else:
        print("Failed to extract float values")
        return None

def try_different_dimensions(floats):
    if not floats:
        return

    # Try common image dimensions and variations
    dimensions = [
        (100, 100), (128, 128), (200, 200), (256, 256), (300, 300), 
        (320, 240), (640, 480), (512, 512), (800, 600), (1024, 768),
        (100, 392), (200, 196), (400, 98), (99, 396)  # Approximately fitting our data
    ]

    for width, height in dimensions:
        if width * height >= len(floats):
            save_float_visualization(floats, width, height, f"float_viz_{width}x{height}.png")

def save_float_visualization(floats, width, height, output_name):
    # Normalize the float values to the range [0, 255]
    if not floats:
        return

    min_val = min(floats)
    max_val = max(floats)
    range_val = max_val - min_val

    if range_val == 0:
        normalized = [0 for _ in floats]
    else:
        normalized = [(f - min_val) / range_val * 255 for f in floats]

    # Create the image
    img_array = np.zeros((height, width), dtype=np.uint8)
    for i in range(min(len(floats), width * height)):
        row = i // width
        col = i % width
        if row < height and col < width:
            img_array[row, col] = int(normalized[i])

    # Save the image
    img = Image.fromarray(img_array, 'L')
    img.save(output_name)
    print(f"Saved visualization as {output_name}")

    # Also try transposing the image
    img_transposed = np.transpose(img_array)
    img_trans = Image.fromarray(img_transposed, 'L')
    img_trans.save(output_name.replace('.png', '_transposed.png'))
    print(f"Saved transposed visualization as {output_name.replace('.png', '_transposed.png')}")

    # Create a version with different color mapping
    # Sometimes this helps reveal hidden patterns
    img_color = Image.fromarray(img_array, 'L')
    img_color = img_color.convert('RGB')
    img_color.save(output_name.replace('.png', '_color.png'))
    print(f"Saved color visualization as {output_name.replace('.png', '_color.png')}")

    # Create a binary threshold version
    threshold = np.mean(normalized)
    binary_img = np.zeros((height, width), dtype=np.uint8)
    for i in range(min(len(floats), width * height)):
        row = i // width
        col = i % width
        if row < height and col < width:
            binary_img[row, col] = 255 if normalized[i] > threshold else 0

    img_binary = Image.fromarray(binary_img, 'L')
    img_binary.save(output_name.replace('.png', '_binary.png'))
    print(f"Saved binary threshold visualization as {output_name.replace('.png', '_binary.png')}")

def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <filename>")
        return

    filename = sys.argv[1]
    floats = extract_float_values(filename)

    if floats:
        # Try a square aspect ratio first
        square_size = int(len(floats) ** 0.5)
        save_float_visualization(floats, square_size, square_size, f"{filename}_square.png")

        # Try different width values
        num_floats = len(floats)
        for width in [99, 100, 128, 200, 256, 300, 400, 500]:
            height = (num_floats + width - 1) // width
            save_float_visualization(floats, width, height, f"{filename}_w{width}.png")

        # Try different height values
        for height in [99, 100, 128, 196, 256, 300, 400]:
            width = (num_floats + height - 1) // height
            save_float_visualization(floats, width, height, f"{filename}_h{height}.png")

        # Try custom dimensions that might fit the data
        try_different_dimensions(floats)

if __name__ == "__main__":
    main()

